//! Synchronous ownership/lifecycle regression tests using real VST3 COM interfaces.
//! These mocks intentionally allocate and lock; these are not real-time-safety tests.

#![allow(non_snake_case)]
#![allow(clippy::unnecessary_cast)] // SDK enum types vary across platforms.

use super::*;
use std::{
    ffi::c_void,
    mem::offset_of,
    sync::atomic::{AtomicBool, AtomicI32, AtomicU64, AtomicUsize, Ordering},
};
use vst3::{
    com_scrape_types::{Header, InterfaceList, MakeHeader, Wrapper},
    Class,
};

#[derive(Clone, Debug, PartialEq, Eq)]
struct Call {
    object: &'static str,
    method: &'static str,
    thread: ThreadId,
}

#[derive(Clone, Default)]
struct Trace(Arc<Mutex<Vec<Call>>>);

impl Trace {
    fn record(&self, object: &'static str, method: &'static str) {
        self.0.lock().unwrap().push(Call {
            object,
            method,
            thread: thread::current().id(),
        });
    }

    fn calls(&self) -> Vec<Call> {
        self.0.lock().unwrap().clone()
    }

    fn clear(&self) {
        self.0.lock().unwrap().clear();
    }

    fn methods(&self) -> Vec<(&'static str, &'static str)> {
        self.calls().iter().map(|c| (c.object, c.method)).collect()
    }

    fn lifecycle(&self) -> Vec<(&'static str, &'static str)> {
        self.methods()
            .into_iter()
            .filter(|(_, method)| matches!(*method, "initialize" | "terminate"))
            .collect()
    }

    fn assert_thread(&self, expected: ThreadId) {
        let calls = self.calls();
        assert!(!calls.is_empty());
        for call in calls {
            assert_eq!(call.thread, expected, "wrong thread for {call:?}");
        }
    }
}

struct Probe {
    name: &'static str,
    trace: Trace,
}

impl Probe {
    fn record(&self, method: &'static str) {
        self.trace.record(self.name, method);
    }
}

trait Recorded {
    fn probe(&self) -> &Probe;
}

// The generated COM vtables delegate their actual addRef/release operations here. Unlike
// checking final Drop alone, this detects even a balanced clone/drop inside a short lease.
#[repr(C)]
struct TrackedObject<C: Class> {
    header: Header<C>,
    references: AtomicUsize,
    value: C,
}

struct TrackedCom;

impl<C: Class + Recorded> Wrapper<C> for TrackedCom {
    unsafe fn data_from_header(header: *mut Header<C>) -> *mut C {
        // repr(C), with header first: every interface offset is generated by MakeHeader.
        ptr::addr_of_mut!((*(header.cast::<TrackedObject<C>>())).value)
    }

    unsafe fn header_from_data(value: *mut C) -> *mut Header<C> {
        value
            .cast::<u8>()
            .sub(offset_of!(TrackedObject<C>, value))
            .cast()
    }

    unsafe fn add_ref(value: *mut C) -> usize {
        let object = Self::header_from_data(value).cast::<TrackedObject<C>>();
        (*value).probe().record("addRef");
        (*object).references.fetch_add(1, Ordering::Relaxed) + 1
    }

    unsafe fn release(value: *mut C) -> usize {
        let object = Self::header_from_data(value).cast::<TrackedObject<C>>();
        (*value).probe().record("release");
        let remaining = (*object).references.fetch_sub(1, Ordering::AcqRel) - 1;
        if remaining == 0 {
            drop(Box::from_raw(object));
        }
        remaining
    }
}

fn tracked<C, I>(value: C) -> ComPtr<I>
where
    C: Class + Recorded + Send + Sync + 'static,
    C::Interfaces: MakeHeader<C, TrackedCom>,
    I: Interface,
{
    let offset = C::Interfaces::query(&I::IID).expect("mock must expose requested interface");
    let object = Box::new(TrackedObject {
        header: <C::Interfaces as MakeHeader<C, TrackedCom>>::HEADER,
        references: AtomicUsize::new(1),
        value,
    });
    // Transfer the allocation's initial owning reference to ComPtr; no hidden wrapper owner.
    unsafe {
        let interface = Box::into_raw(object)
            .cast::<u8>()
            .offset(offset)
            .cast::<I>();
        ComPtr::from_raw(interface).unwrap()
    }
}

struct MockState {
    output_buses: AtomicI32,
    channels: AtomicI32,
    expand_on_state: AtomicBool,
    change_on_refusal: AtomicBool,
    fail_setup: AtomicBool,
    fail_process: AtomicBool,
    fail_deactivate: AtomicBool,
    contexts: Mutex<Vec<usize>>,
    processed_layouts: Mutex<Vec<Vec<i32>>>,
    processed_parameters: Mutex<Vec<Vec<(u32, i32, f64)>>>,
    capture_callback: Mutex<Option<Box<dyn Fn() + Send + Sync>>>,
    process_callback: Mutex<Option<Box<dyn Fn() + Send + Sync>>>,
    fail_state: AtomicBool,
    no_alloc_process: AtomicBool,
    realtime_calls: AtomicUsize,
    realtime_points: AtomicUsize,
    processed_event_count: AtomicUsize,
    output_points: AtomicUsize,
    output_event_attempts: AtomicUsize,
    rejected_output_events: AtomicUsize,
    last_mirrored: AtomicU64,
}

impl Default for MockState {
    fn default() -> Self {
        Self {
            output_buses: AtomicI32::new(1),
            channels: AtomicI32::new(1),
            expand_on_state: AtomicBool::new(false),
            change_on_refusal: AtomicBool::new(false),
            fail_setup: AtomicBool::new(false),
            fail_process: AtomicBool::new(false),
            fail_deactivate: AtomicBool::new(false),
            contexts: Mutex::new(Vec::new()),
            processed_layouts: Mutex::new(Vec::new()),
            processed_parameters: Mutex::new(Vec::new()),
            capture_callback: Mutex::new(None),
            process_callback: Mutex::new(None),
            fail_state: AtomicBool::new(false),
            no_alloc_process: AtomicBool::new(false),
            realtime_calls: AtomicUsize::new(0),
            realtime_points: AtomicUsize::new(0),
            processed_event_count: AtomicUsize::new(0),
            output_points: AtomicUsize::new(0),
            output_event_attempts: AtomicUsize::new(0),
            rejected_output_events: AtomicUsize::new(0),
            last_mirrored: AtomicU64::new(0),
        }
    }
}

// The same minimal implementation is exposed through three distinct interface lists.
// A separate controller is a genuinely distinct COM allocation with no IComponent interface.
struct MockPlugin<const SINGLE: bool, const CONTROLLER: bool> {
    probe: Probe,
    state: Arc<MockState>,
}

impl Class for MockPlugin<true, false> {
    type Interfaces = (IComponent, IAudioProcessor, IEditController);
}
impl Class for MockPlugin<false, false> {
    type Interfaces = (IComponent, IAudioProcessor);
}
impl Class for MockPlugin<false, true> {
    type Interfaces = (IEditController,);
}

impl<const S: bool, const C: bool> Recorded for MockPlugin<S, C> {
    fn probe(&self) -> &Probe {
        &self.probe
    }
}

impl<const S: bool, const C: bool> Drop for MockPlugin<S, C> {
    fn drop(&mut self) {
        self.probe.record("drop");
    }
}

impl<const S: bool, const C: bool> IPluginBaseTrait for MockPlugin<S, C> {
    unsafe fn initialize(&self, context: *mut FUnknown) -> tresult {
        self.probe.record("initialize");
        self.state.contexts.lock().unwrap().push(context as usize);
        kResultOk
    }
    unsafe fn terminate(&self) -> tresult {
        self.probe.record("terminate");
        kResultOk
    }
}

const CONTROLLER_CID: TUID = vst3::uid(0x4F574E45, 0x52534849, 0x50544553, 0x54000001);

impl<const S: bool, const C: bool> IComponentTrait for MockPlugin<S, C> {
    unsafe fn getControllerClassId(&self, cid: *mut TUID) -> tresult {
        self.probe.record("getControllerClassId");
        if S {
            return kNotImplemented;
        }
        *cid = CONTROLLER_CID;
        kResultOk
    }
    unsafe fn setIoMode(&self, _mode: IoMode) -> tresult {
        kResultOk
    }
    unsafe fn getBusCount(&self, media: MediaType, direction: BusDirection) -> i32 {
        self.probe.record("getBusCount");
        if media == kAudio as i32 && direction == kOutput as i32 {
            self.state.output_buses.load(Ordering::Relaxed)
        } else {
            0
        }
    }
    unsafe fn getBusInfo(
        &self,
        media: MediaType,
        direction: BusDirection,
        index: i32,
        info: *mut BusInfo,
    ) -> tresult {
        self.probe.record("getBusInfo");
        if media != kAudio as i32
            || direction != kOutput as i32
            || index < 0
            || index >= self.state.output_buses.load(Ordering::Relaxed)
        {
            return kInvalidArgument;
        }
        let mut bus: BusInfo = std::mem::zeroed();
        bus.mediaType = media;
        bus.direction = direction;
        bus.channelCount = self.state.channels.load(Ordering::Relaxed);
        bus.busType = BusTypes_::kMain as i32;
        bus.flags = BusInfo_::BusFlags_::kDefaultActive as u32;
        *info = bus;
        kResultOk
    }
    unsafe fn getRoutingInfo(
        &self,
        _input: *mut RoutingInfo,
        _output: *mut RoutingInfo,
    ) -> tresult {
        kNotImplemented
    }
    unsafe fn activateBus(
        &self,
        _media: MediaType,
        _direction: BusDirection,
        _index: i32,
        _state: TBool,
    ) -> tresult {
        self.probe.record("activateBus");
        kResultOk
    }
    unsafe fn setActive(&self, state: TBool) -> tresult {
        self.probe.record(if state == 0 {
            "setActive(false)"
        } else {
            "setActive(true)"
        });
        if state == 0 && self.state.fail_deactivate.load(Ordering::Relaxed) {
            kResultFalse
        } else {
            kResultOk
        }
    }
    unsafe fn setState(&self, _stream: *mut IBStream) -> tresult {
        self.probe.record("component.setState");
        if self.state.fail_state.load(Ordering::Acquire) {
            return kResultFalse;
        }
        if self.state.expand_on_state.load(Ordering::Relaxed) {
            self.state.output_buses.store(2, Ordering::Relaxed);
            self.state.channels.store(2, Ordering::Relaxed);
        }
        kResultOk
    }
    unsafe fn getState(&self, stream: *mut IBStream) -> tresult {
        self.probe.record("component.getState");
        if let Some(callback) = self.state.capture_callback.lock().unwrap().as_ref() {
            callback();
        }
        let stream = vst3::ComRef::from_raw(stream).unwrap();
        let mut value = 42u8;
        stream.write((&mut value as *mut u8).cast(), 1, ptr::null_mut())
    }
}

impl<const S: bool, const C: bool> IAudioProcessorTrait for MockPlugin<S, C> {
    unsafe fn setBusArrangements(
        &self,
        _inputs: *mut SpeakerArrangement,
        _num_inputs: i32,
        _outputs: *mut SpeakerArrangement,
        _num_outputs: i32,
    ) -> tresult {
        self.probe.record("setBusArrangements");
        if self.state.change_on_refusal.load(Ordering::Relaxed) {
            self.state.channels.store(2, Ordering::Relaxed);
            kResultFalse
        } else {
            kResultOk
        }
    }
    unsafe fn getBusArrangement(
        &self,
        direction: BusDirection,
        index: i32,
        arrangement: *mut SpeakerArrangement,
    ) -> tresult {
        self.probe.record("getBusArrangement");
        if direction != kOutput as i32
            || index < 0
            || index >= self.state.output_buses.load(Ordering::Relaxed)
        {
            return kInvalidArgument;
        }
        *arrangement = if self.state.channels.load(Ordering::Relaxed) == 1 {
            SpeakerArr::kMono
        } else {
            SpeakerArr::kStereo
        };
        kResultOk
    }
    unsafe fn canProcessSampleSize(&self, size: i32) -> tresult {
        if size == SymbolicSampleSizes_::kSample32 as i32 {
            kResultOk
        } else {
            kResultFalse
        }
    }
    unsafe fn getLatencySamples(&self) -> u32 {
        0
    }
    unsafe fn setupProcessing(&self, _setup: *mut ProcessSetup) -> tresult {
        self.probe.record("setupProcessing");
        if self.state.fail_setup.load(Ordering::Relaxed) {
            kResultFalse
        } else {
            kResultOk
        }
    }
    unsafe fn setProcessing(&self, state: TBool) -> tresult {
        self.probe.record(if state == 0 {
            "setProcessing(false)"
        } else {
            "setProcessing(true)"
        });
        kResultOk
    }
    unsafe fn process(&self, data: *mut ProcessData) -> tresult {
        if let Some(events) = vst3::ComRef::from_raw((*data).inputEvents) {
            self.state
                .processed_event_count
                .fetch_add(events.getEventCount() as usize, Ordering::Relaxed);
        }
        if self.state.no_alloc_process.load(Ordering::Acquire) {
            // Dedicated fixed-state processor path: no trace Vec, formatting or callback hook.
            // Parameter/scalar-event operations use prepared storage; data exchange stays empty.
            let data = &mut *data;
            self.state.realtime_calls.fetch_add(1, Ordering::Relaxed);
            let mut point_count = 0;
            if let Some(changes) = vst3::ComRef::from_raw(data.inputParameterChanges) {
                for index in 0..changes.getParameterCount() {
                    let queue = vst3::ComRef::from_raw(changes.getParameterData(index)).unwrap();
                    for point in 0..queue.getPointCount() {
                        let (mut offset, mut value) = (0, 0.0);
                        assert_eq!(queue.getPoint(point, &mut offset, &mut value), kResultOk);
                        point_count += 1;
                    }
                }
            }
            self.state
                .realtime_points
                .store(point_count, Ordering::Release);
            let output_count = self.state.output_points.load(Ordering::Acquire);
            if output_count != 0 {
                let output = vst3::ComRef::from_raw(data.outputParameterChanges).unwrap();
                let queue =
                    vst3::ComRef::from_raw(output.addParameterData(&77, ptr::null_mut())).unwrap();
                for point in 0..output_count {
                    // Deliberately ignore write failures, like an uncooperative plugin.
                    let _ = queue.addPoint(point as i32, 0.5, ptr::null_mut());
                }
            }
            let output_events = self.state.output_event_attempts.load(Ordering::Acquire);
            if output_events != 0 {
                let output = vst3::ComRef::from_raw(data.outputEvents).unwrap();
                for index in 0..output_events {
                    let mut event: Event = std::mem::zeroed();
                    event.r#type = Event_::EventTypes_::kNoteOffEvent as u16;
                    event.__field0.noteOff = NoteOffEvent {
                        channel: 0,
                        pitch: 60,
                        velocity: 0.0,
                        noteId: index as i32,
                        tuning: 0.0,
                    };
                    // A plugin may ignore the returned rejection and still report success.
                    if output.addEvent(&mut event) != kResultOk {
                        self.state
                            .rejected_output_events
                            .fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            return if self.state.fail_process.load(Ordering::Acquire) {
                kResultFalse
            } else {
                kResultOk
            };
        }
        self.probe.record("process");
        if self.state.fail_process.load(Ordering::Acquire) {
            return kResultFalse;
        }
        let data = &mut *data;
        let mut parameters = Vec::new();
        if let Some(changes) = vst3::ComRef::from_raw(data.inputParameterChanges) {
            for index in 0..changes.getParameterCount() {
                let queue = vst3::ComRef::from_raw(changes.getParameterData(index)).unwrap();
                for point in 0..queue.getPointCount() {
                    let (mut offset, mut value) = (0, 0.0);
                    assert_eq!(queue.getPoint(point, &mut offset, &mut value), kResultOk);
                    parameters.push((queue.getParameterId(), offset, value));
                }
            }
        }
        self.state
            .processed_parameters
            .lock()
            .unwrap()
            .push(parameters);
        if let Some(callback) = self.state.process_callback.lock().unwrap().as_ref() {
            callback();
        }
        let mut layout = Vec::new();
        for index in 0..data.numOutputs.max(0) as usize {
            let bus = &mut *data.outputs.add(index);
            layout.push(bus.numChannels);
            for channel in 0..bus.numChannels.max(0) as usize {
                let samples = *bus.__field0.channelBuffers32.add(channel);
                // Inactive buses have null channel pointers. Their slot must still survive.
                if !samples.is_null() {
                    for sample in 0..data.numSamples.max(0) as usize {
                        *samples.add(sample) = (index * 10 + channel + 1) as f32;
                    }
                }
            }
            bus.silenceFlags = 0;
        }
        self.state.processed_layouts.lock().unwrap().push(layout);
        kResultOk
    }
    unsafe fn getTailSamples(&self) -> u32 {
        0
    }
}

