struct MockFactory {
    probe: Probe,
    state: Arc<MockState>,
}
impl Class for MockFactory {
    type Interfaces = (IPluginFactory,);
}
impl Recorded for MockFactory {
    fn probe(&self) -> &Probe {
        &self.probe
    }
}
impl Drop for MockFactory {
    fn drop(&mut self) {
        self.probe.record("drop");
    }
}
impl IPluginFactoryTrait for MockFactory {
    unsafe fn getFactoryInfo(&self, _info: *mut PFactoryInfo) -> tresult {
        kNotImplemented
    }
    unsafe fn countClasses(&self) -> i32 {
        1
    }
    unsafe fn getClassInfo(&self, _index: i32, _info: *mut PClassInfo) -> tresult {
        kNotImplemented
    }
    unsafe fn createInstance(
        &self,
        cid: FIDString,
        iid: FIDString,
        object: *mut *mut c_void,
    ) -> tresult {
        self.probe.record("createInstance");
        if cid.is_null() || iid.is_null() || object.is_null() {
            return kInvalidArgument;
        }
        *object = ptr::null_mut();
        if ptr::read_unaligned(cid.cast::<TUID>()) != CONTROLLER_CID
            || std::slice::from_raw_parts(iid.cast::<u8>(), 16) != IEditController::IID.as_slice()
        {
            return kNoInterface;
        }
        *object = tracked::<_, IEditController>(MockPlugin::<false, true> {
            probe: Probe {
                name: "controller",
                trace: self.probe.trace.clone(),
            },
            state: self.state.clone(),
        })
        .into_raw()
        .cast();
        kResultOk
    }
}

fn factory(trace: &Trace, state: &Arc<MockState>) -> ComPtr<IPluginFactory> {
    tracked(MockFactory {
        probe: Probe {
            name: "factory",
            trace: trace.clone(),
        },
        state: state.clone(),
    })
}

#[test]
fn single_component_controller_alias_initializes_and_terminates_once() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    let component: ComPtr<IComponent> = tracked(MockPlugin::<true, false> {
        probe: Probe {
            name: "component",
            trace: trace.clone(),
        },
        state: state.clone(),
    });
    let factory = factory(&trace, &state);
    let host = create_host_application();
    let context = host.as_com_ref::<FUnknown>().unwrap().as_ptr();
    unsafe {
        assert_eq!(component.initialize(context), kResultOk);
        let controller = PluginImpl::get_or_create_controller(&component, &factory, context)
            .unwrap()
            .expect("single-component controller alias");
        assert_eq!(
            component.cast::<FUnknown>().unwrap().as_ptr(),
            controller.cast::<FUnknown>().unwrap().as_ptr()
        );
        terminate_component(&component, Some(&controller), true, None);
        drop(controller);
    }
    drop(component);
    assert_eq!(
        trace.lifecycle(),
        [("component", "initialize"), ("component", "terminate")]
    );
    assert!(!trace
        .methods()
        .iter()
        .any(|(_, method)| *method == "createInstance" || *method == "getControllerClassId"));
    assert_eq!(
        trace
            .methods()
            .iter()
            .filter(|call| **call == ("component", "drop"))
            .count(),
        1
    );
    assert_eq!(*state.contexts.lock().unwrap(), [context as usize]);
    trace.assert_thread(thread::current().id());
}

#[test]
fn separate_controller_initializes_with_host_and_terminates_before_component() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    let component: ComPtr<IComponent> = tracked(MockPlugin::<false, false> {
        probe: Probe {
            name: "component",
            trace: trace.clone(),
        },
        state: state.clone(),
    });
    let factory = factory(&trace, &state);
    let host = create_host_application();
    let context = host.as_com_ref::<FUnknown>().unwrap().as_ptr();
    unsafe {
        assert_eq!(component.initialize(context), kResultOk);
        let controller = PluginImpl::get_or_create_controller(&component, &factory, context)
            .unwrap()
            .expect("factory-created controller");
        assert!(controller.cast::<IComponent>().is_none());
        terminate_component(&component, Some(&controller), false, None);
        drop(controller);
    }
    drop(component);
    assert_eq!(
        trace.lifecycle(),
        [
            ("component", "initialize"),
            ("controller", "initialize"),
            ("controller", "terminate"),
            ("component", "terminate"),
        ]
    );
    assert_eq!(
        *state.contexts.lock().unwrap(),
        [context as usize, context as usize]
    );
    for name in ["component", "controller"] {
        assert_eq!(
            trace
                .methods()
                .iter()
                .filter(|call| **call == (name, "drop"))
                .count(),
            1
        );
    }
    trace.assert_thread(thread::current().id());
}

#[test]
fn processor_lease_performs_no_com_reference_count_operations() {
    let trace = Trace::default();
    let mut processor: ComPtr<IAudioProcessor> = tracked(MockPlugin::<true, false> {
        probe: Probe {
            name: "processor",
            trace: trace.clone(),
        },
        state: Arc::new(MockState::default()),
    });
    // Calibrate instrumentation: a balanced owning clone really does appear in the trace.
    drop(processor.clone());
    assert_eq!(
        trace.methods(),
        [("processor", "addRef"), ("processor", "release")]
    );
    trace.clear();
    {
        let module = MockModule(Trace::default());
        let mut lease = ProcessorLease::new(&mut processor, &module);
        assert_eq!(lease.set_processing(1), kResultOk);
        // Zero buses and zero samples are sufficient for this notification-only mock call.
        let mut data: ProcessData = unsafe { std::mem::zeroed() };
        assert_eq!(unsafe { lease.process(&mut data) }, kResultOk);
        assert_eq!(lease.set_processing(0), kResultOk);
    }
    assert_eq!(
        trace.methods(),
        [
            ("processor", "setProcessing(true)"),
            ("processor", "process"),
            ("processor", "setProcessing(false)"),
        ]
    );
    drop(processor);
    assert_eq!(
        &trace.methods()[3..],
        [("processor", "release"), ("processor", "drop")]
    );
    trace.assert_thread(thread::current().id());
}

struct MockModule(Trace);
impl VstModule for MockModule {
    fn get_factory(&self) -> Result<*mut IPluginFactory> {
        Err(Error::Other("fixture supplies its factory directly".into()))
    }
    fn path(&self) -> &std::path::Path {
        std::path::Path::new("ownership-test.vst3")
    }
}
impl Drop for MockModule {
    fn drop(&mut self) {
        self.0.record("module", "drop");
    }
}

