/// Check each SDK pointer against the owning host vectors, rather than requiring allocator
/// addresses to differ across rebuilds (an allocator may legitimately reuse an address).
fn assert_prepared_layout(plugin: &PluginImpl, buses: usize, channels: usize) {
    let data = plugin
        .runtime
        .process_data
        .as_ref()
        .expect("prepared process data");
    assert_eq!(data.process_data.numOutputs as usize, buses);
    assert_eq!(data.output_bus_buffers.len(), buses);
    assert_eq!(
        data.process_data.outputs as *const AudioBusBuffers,
        data.output_bus_buffers.as_ptr()
    );
    let HostSampleBuffers::F32(samples) = &data.sample_buffers else {
        panic!("expected f32 fixture");
    };
    assert_eq!(samples.outputs.len(), buses * channels);
    for (index, bus) in data.output_bus_buffers.iter().enumerate() {
        assert_eq!(bus.numChannels as usize, channels);
        let pointers = &samples.output_channel_ptrs.0[index];
        assert_eq!(pointers.len(), channels);
        assert_eq!(
            unsafe { bus.__field0.channelBuffers32 } as *const *mut f32,
            pointers.as_ptr()
        );
        for (channel, pointer) in pointers.iter().enumerate() {
            assert_eq!(
                *pointer as *const f32,
                samples.outputs[index * channels + channel].as_ptr()
            );
        }
    }
    assert_eq!(plugin.output_channel_count(), buses * channels);
}

fn process_and_assert_samples(plugin: &mut PluginImpl, buses: usize, channels: usize) {
    let mut buffers = AudioBuffers::new(0, buses * channels, 16, 48000.0);
    plugin.process(&mut buffers).unwrap();
    for bus in 0..buses {
        for channel in 0..channels {
            assert_eq!(
                buffers.outputs[bus * channels + channel],
                vec![(bus * 10 + channel + 1) as f32; 16]
            );
        }
    }
}

#[test]
fn load_state_refreshes_bus_counts_channel_pointers_and_processing_layout() {
    let trace = Trace::default();
    let state = Arc::new(MockState::default());
    let mut plugin = plugin_fixture(&trace, &state);
    plugin.start_processing().unwrap();
    assert_prepared_layout(&plugin, 1, 1);
    process_and_assert_samples(&mut plugin, 1, 1);

    state.expand_on_state.store(true, Ordering::Relaxed);
    let snapshot = encode_state_snapshot(&StateSnapshot {
        component: vec![1],
        controller: None,
    })
    .unwrap();
    plugin
        .load_state_with_context(&snapshot, &StateContext::Project)
        .unwrap();
    assert!(plugin.runtime.is_processing);
    assert_prepared_layout(&plugin, 2, 2);
    trace.clear();
    process_and_assert_samples(&mut plugin, 2, 2);
    assert_eq!(
        trace.methods(),
        [("component", "process")],
        "prepared processing must not query COM bus metadata or clone interfaces"
    );
    assert_eq!(
        *state.processed_layouts.lock().unwrap(),
        [vec![1], vec![2, 2]]
    );
}

